"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["2500"],{35925(t){t.exports=JSON.parse('{"tag":{"label":"ux-writing","permalink":"/flamingo/tags/ux-writing","allTagsPath":"/flamingo/tags","count":35,"items":[{"id":"components/buttons/floating-button/content","title":"Content","description":"The floating button carries a short text label (plus an optional icon) \u2014 the same button text","permalink":"/flamingo/components/buttons/floating-button/content"},{"id":"components/buttons/floating-icon-button/content","title":"Content","description":"The floating icon button has no text label by design \u2014 its icon must be immediately recognisable","permalink":"/flamingo/components/buttons/floating-icon-button/content"},{"id":"components/buttons/icon-button/content","title":"Content","description":"The icon button has no text label by design \u2014 all of its meaning comes from the icon itself, so the","permalink":"/flamingo/components/buttons/icon-button/content"},{"id":"components/buttons/primary-button/content","title":"Content","description":"Buttons use short, clear text that communicates what the user can expect from interacting with that","permalink":"/flamingo/components/buttons/primary-button/content"},{"id":"components/buttons/secondary-button/content","title":"Content","description":"Buttons use short, clear text that communicates what the user can expect from interacting with that","permalink":"/flamingo/components/buttons/secondary-button/content"},{"id":"components/buttons/tertiary-button/content","title":"Content","description":"Buttons use short, clear text that communicates what the user can expect from interacting with that","permalink":"/flamingo/components/buttons/tertiary-button/content"},{"id":"components/content-display-and-lists/expandable-list/content","title":"Content","description":"The collapsed row should already convey the most important information (what the item is, its","permalink":"/flamingo/components/content-display-and-lists/expandable-list/content"},{"id":"components/content-display-and-lists/leading-list/content","title":"Content","description":"Row titles should name the destination or setting clearly and concisely \u2014 a user should know","permalink":"/flamingo/components/content-display-and-lists/leading-list/content"},{"id":"components/feedback/badge/content","title":"Content","description":"- Keep the label as short as possible \u2014 a number, or a word or two at most.","permalink":"/flamingo/components/feedback/badge/content"},{"id":"components/feedback/message-bar/content","title":"Content","description":"- Title: state the ongoing status plainly \u2014 \\"Location Services Off,\\" not a vague prompt.","permalink":"/flamingo/components/feedback/message-bar/content"},{"id":"components/feedback/message-box/content","title":"Content","description":"- Title: state the situation plainly \u2014 \\"You\'ve reached the cash limit\\" rather than something","permalink":"/flamingo/components/feedback/message-box/content"},{"id":"components/feedback/snackbar/content","title":"Content","description":"- Keep the message to one short line \u2014 the snackbar disappears automatically after a few seconds,","permalink":"/flamingo/components/feedback/snackbar/content"},{"id":"components/feedback/tag/content","title":"Content","description":"- Keep the label to a single word or short phrase \u2014 long labels get truncated (see Guidelines).","permalink":"/flamingo/components/feedback/tag/content"},{"id":"components/form/checkbox/content","title":"Content","description":"- Phrase each label as the option itself, not a question \u2014 \\"Bike,\\" not \\"Do you want a bike?\\"","permalink":"/flamingo/components/form/checkbox/content"},{"id":"components/form/chips/content","title":"Content","description":"- Keep chip labels to one or two words.","permalink":"/flamingo/components/form/chips/content"},{"id":"components/form/drop-down/content","title":"Content","description":"- Keep the Field title short and specific \u2014 describe what\'s being chosen.","permalink":"/flamingo/components/form/drop-down/content"},{"id":"components/form/radio-button/content","title":"Content","description":"- Phrase each option as the choice itself, not a question \u2014 \\"English,\\" not \\"Do you speak English?\\"","permalink":"/flamingo/components/form/radio-button/content"},{"id":"components/form/switch/content","title":"Content","description":"- Phrase the label as the state being enabled, not a question \u2014 \\"Enable dark mode,\\" not \\"Do you want dark mode?\\"","permalink":"/flamingo/components/form/switch/content"},{"id":"components/form/text-area/content","title":"Content","description":"- Keep the Field title short and specific \u2014 describe what to enter.","permalink":"/flamingo/components/form/text-area/content"},{"id":"components/form/text-field/content","title":"Content","description":"- Keep the Field title short and specific \u2014 describe what to enter, not an instruction (\\"Email,\\" not \\"Enter your email\\").","permalink":"/flamingo/components/form/text-field/content"},{"id":"components/form/tile/content","title":"Content","description":"- Keep the label to one short word or phrase \u2014 long labels make the tile grow and break grid alignment with its siblings.","permalink":"/flamingo/components/form/tile/content"},{"id":"components/layout/empty-screen/content","title":"Content","description":"- Title: state plainly what\'s missing \u2014 \\"No deliveries yet\\" rather than something vague or","permalink":"/flamingo/components/layout/empty-screen/content"},{"id":"components/navigation/content-header/content","title":"Content","description":"- Keep titles short and specific to the section \u2014 avoid generic labels like \\"Info\\" or \\"Details.\\"","permalink":"/flamingo/components/navigation/content-header/content"},{"id":"components/navigation/header/content","title":"Content","description":"- Keep the title to one or two words wherever possible \u2014 it must fit on one line without truncating.","permalink":"/flamingo/components/navigation/header/content"},{"id":"components/navigation/tabs/content","title":"Content","description":"- Keep each tab label to a word or two \u2014 long labels get truncated (see Guidelines).","permalink":"/flamingo/components/navigation/tabs/content"},{"id":"components/overlay/action-picker/content","title":"Content","description":"- Phrase each action as a verb \u2014 \\"Delete document,\\" not \\"Deletion.\\"","permalink":"/flamingo/components/overlay/action-picker/content"},{"id":"components/overlay/bottom-sheet/content","title":"Content","description":"- Keep the title short and specific to what the sheet is for.","permalink":"/flamingo/components/overlay/bottom-sheet/content"},{"id":"components/overlay/date-picker/content","title":"Content","description":"- Label the confirm action with the specific outcome, e.g. \\"Select date,\\" not a generic \\"OK.\\"","permalink":"/flamingo/components/overlay/date-picker/content"},{"id":"components/overlay/option-picker/content","title":"Content","description":"- Title the picker with what\'s being chosen, e.g. \\"Select country.\\"","permalink":"/flamingo/components/overlay/option-picker/content"},{"id":"components/overlay/time-picker/content","title":"Content","description":"- Label the confirm action with the specific outcome, e.g. \\"Select time,\\" not a generic \\"OK.\\"","permalink":"/flamingo/components/overlay/time-picker/content"},{"id":"components/progressors-and-charts/circle-chart/content","title":"Content","description":"- Keep the main label short \u2014 a number or short percentage, not a sentence.","permalink":"/flamingo/components/progressors-and-charts/circle-chart/content"},{"id":"components/progressors-and-charts/pie-chart/content","title":"Content","description":"- Show the main label as a fraction (e.g. \\"6/7\\"), not a percentage \u2014 that\'s what the Circle Chart is for.","permalink":"/flamingo/components/progressors-and-charts/pie-chart/content"},{"id":"components/progressors-and-charts/sectioned-progress-bar/content","title":"Content","description":"- Keep milestone labels to one or two words.","permalink":"/flamingo/components/progressors-and-charts/sectioned-progress-bar/content"},{"id":"components/progressors-and-charts/specs-bar-chart/content","title":"Content","description":"- Keep axis labels short \u2014 long labels may wrap or get clipped, especially in translated locales.","permalink":"/flamingo/components/progressors-and-charts/specs-bar-chart/content"},{"id":"components/progressors-and-charts/stepper/content","title":"Content","description":"- Title each step with the action or milestone it represents, not just \\"Step 1.\\"","permalink":"/flamingo/components/progressors-and-charts/stepper/content"}],"unlisted":false}}')}}]);